/**
 * DEV-ONLY entry point — Main A + Main B preview, no calibration / instructions / practice.
 *
 * Reachable at /dev-main.html during `npm run dev` — Vite serves at
 * http://localhost:5273 by default (`vite.config.js`; port must match the terminal).
 * NOT included in the production bundle by default; Vite still picks it up
 * because dev-main.html sits at project root, so it's only a dev convenience.
 *
 * What it does NOT include (relative to the production runner.js):
 *   - Calibration chain (consent / demographics / screen / volume / fullscreen / tones-fam)
 *   - Visual primitives demo
 *   - Instructions chain (memory / imagery / dual + 3 attention checks)
 *   - Practice block + accuracy gate
 *   - Strategy + music-experience questionnaires
 *   - Chunked uploader + completion-URL redirect
 *
 * What it DOES include:
 *   - Session init (PRNG seed from query string or fabricated preview ids)
 *   - Storage init (IndexedDB / memory fallback)
 *   - Main A (60 trials), 5-second rest, Main B (60 trials)
 *   - End screen with a "see the data" prompt
 *
 * Quit anytime with Ctrl+W or by clicking "Stop" in the browser. The data
 * stays in jsPsych's in-memory store + IndexedDB for inspection in DevTools:
 *
 *   window.jsPsych.data.get().json()
 */
import { initJsPsych } from 'jspsych';
import htmlKeyboardResponse from '@jspsych/plugin-html-keyboard-response';

import { config } from './config.js';
import { initSession } from './prolific.js';
import { generateMainBlockPair } from './scheduler/main-blocks.js';
import { restNode } from './conditions/rest.js';
import { initStorage, appendTrialRow } from './storage.js';

const session = initSession();
const storageReadyPromise = initStorage();

const jsPsych = initJsPsych({
  display_element: undefined,
  on_data_update: (datum) => {
    appendTrialRow(datum).catch((err) => {
      console.error('[dev-main] storage append failed', err);
    });
  },
  on_finish: () => {
    const data = jsPsych.data.get();
    data.addProperties({
      session_id: session.params.session_id,
      prolific_pid: session.params.prolific_pid,
      study_id: session.params.study_id,
      is_preview: session.params.is_preview,
      is_pilot_run: session.is_pilot_run,
      pilot_label: session.pilot_label,
      prng_seed_uint32: session.prng_seed_uint32,
      schema_version: session.schema_version,
      build_id: session.build_id,
      dev_entry: 'dev-main',
    });
    console.info('[dev-main] session finished', session);
    console.info('[dev-main] data accessible at window.jsPsych.data.get()');
  },
});
window.jsPsych = jsPsych;

const devIntro = {
  type: htmlKeyboardResponse,
  stimulus: `
    <div style="max-width: 36rem; margin: 0 auto; text-align: left;">
      <h2 style="text-align: center;">DEV — Main blocks preview</h2>
      <p>This is a developer-only entry for inspecting the main experimental
      conditions. No calibration, instructions, practice, or questionnaires &mdash; straight
      into the 60-trial Main A and Main B blocks.</p>
      <p><strong>Controls:</strong></p>
      <ul>
        <li><kbd>→</kbd> &nbsp;= yes / on / present / high tone (depending on trial type)</li>
        <li><kbd>←</kbd> &nbsp;= no / off / absent / low tone</li>
        <li>Imagery probe (star): press the arrow key the star points to.</li>
      </ul>
      <p>You'll see all five trial types interleaved: D-only, T-only, I-only,
      I+D (imagery + dot memory), I+T (imagery + tone memory).</p>
      <p>Quit anytime — your in-memory data is at
      <code>window.jsPsych.data.get()</code> in DevTools.</p>
      <p>Build <code>${config.build_id}</code>.</p>
      <p style="text-align: center;">Press <kbd>Space</kbd> to begin Main A.</p>
    </div>
  `,
  choices: [' '],
  data: { phase: 'dev_main_intro' },
};

const mainAIntro = {
  type: htmlKeyboardResponse,
  stimulus: `
    <div style="max-width: 36rem; margin: 0 auto;">
      <h2>Main task — Block 1 of 2</h2>
      <p>Block 1: 60 trials. Press <kbd>Space</kbd> to begin.</p>
    </div>
  `,
  choices: [' '],
  data: { phase: 'main_a_intro' },
};

const mainBIntro = {
  type: htmlKeyboardResponse,
  stimulus: `
    <div style="max-width: 36rem; margin: 0 auto;">
      <h2>Main task — Block 2 of 2</h2>
      <p>Block 2: 60 trials. Press <kbd>Space</kbd> to begin.</p>
    </div>
  `,
  choices: [' '],
  data: { phase: 'main_b_intro' },
};

const endScreen = {
  type: htmlKeyboardResponse,
  stimulus: `
    <div style="max-width: 36rem; margin: 0 auto;">
      <h2>Done — DEV preview</h2>
      <p>You've completed both main blocks in dev-preview mode. The data is
      still in memory; open DevTools and run
      <code>window.jsPsych.data.get().json()</code> to inspect.</p>
      <p>To preview the full session (calibration → instructions → practice →
      Main A → Main B → questionnaires), open <code>/</code> instead of
      <code>/dev-main.html</code>.</p>
      <p>Press <kbd>Space</kbd> to close.</p>
    </div>
  `,
  choices: [' '],
  data: { phase: 'dev_main_end' },
};

const mainPair = generateMainBlockPair();

const timeline = [
  devIntro,
  mainAIntro,
  ...mainPair.mainA.nodes,
  restNode({ durationS: 5, blockLabel: 'dev_inter_block' }),
  mainBIntro,
  ...mainPair.mainB.nodes,
  endScreen,
];

storageReadyPromise.then(() => jsPsych.run(timeline));
